tools.input_schema_source:
inputSchema: {
        action: z.string().optional().describe("Action or registered tool name. Use list_actions to see what this server mode allows."),
        args: z.record(z.string(), z.any()).optional().describe("Arguments for the selected action. Same shape as the wrapped CodexPro tool.")
      },

inputSchema: {
        action_id: z.string().regex(/^cpa_[a-f0-9]{32}$/).describe("Stable CodexPro action id returned by activity_list.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        include_global_skills: z.boolean().optional().describe("Include user and plugin skill folders. Default: true."),
        include_mcp_servers: z.boolean().optional().describe("Include configured MCP server names from safe config files. Default: true."),
        max_skills: z.number().int().min(1).max(500).optional().describe("Maximum skills to list. Default: 120.")
      },

inputSchema: {
        include_tree: z.boolean().optional().describe("Include a compact file tree. Default: false for speed."),
        max_depth: z.number().int().min(1).max(8).optional().describe("Tree depth when include_tree=true. Default: 2."),
        include_skills: z.boolean().optional().describe("Discover skills by name/description. Default: false for speed."),
        include_global_skills: z.boolean().optional().describe("Also scan installed user/plugin skills when include_skills=true. Default: false.")
      },

inputSchema: config.worktreeMode === "mcp"
        ? {
            workspace_id: z.string().describe("Stable workspace_id returned by create_workspace."),
            include_tree: z.boolean().optional().describe("Include a compact file tree. Default: true."),
            max_depth: z.number().int().min(1).max(8).optional().describe("Tree depth. Default: 3."),
            max_entries: z.number().int().min(1).max(3000).optional().describe("Maximum tree entries. Default: 500."),
            include_skills: z.boolean().optional().describe("Discover skills by name/description. Default: false for speed."),
            include_global_skills: z.boolean().optional().describe("Also scan installed user/plugin skills when include_skills=true. Default: false.")
          }
        : {
            ...(ctx.work ? { workspace_id: z.string().optional().describe("A retained workspace returned by work_status; loads its project instructions.") } : {}),
            project_id: z.string().min(1).optional().describe("One project id from list_projects. Cannot be combined with project_ids."),
            project_ids: z.array(z.string().min(1)).min(1).max(12).optional().describe(
              "Open several projects in one call. Duplicate ids are collapsed; the first project becomes the selected primary workspace. Cannot be combined with project_id."
            ),
            ...(config.projectsFile
              ? {}
              : {
                  root: z.string().optional().describe("Project directory to open. Omit to use CODEXPRO_ROOT/current working directory. Supports ~/ paths."),
                  path: z.string().optional().describe("Alias for root. Useful for clients that naturally send path instead of root.")
                }),
            include_tree: z.boolean().optional().describe(
              "Include compact file trees. Defaults to true for a newly opened singular workspace, false for repeated singular opens and project_ids arrays."
            ),
            max_depth: z.number().int().min(1).max(8).optional().describe("Tree depth. Default: 3."),
            max_entries: z.number().int().min(1).max(3000).optional().describe(
              "Maximum tree entries. Default: 500. With project_ids, this is one total budget divided across the opened workspaces."
            ),
            include_skills: z.boolean().optional().describe("Discover skills by name/description. Default: false for speed."),
            include_global_skills: z.boolean().optional().describe("Also scan installed user/plugin skills when include_skills=true. Default: false."),
            bootstrap_context: z.boolean().optional().describe("Deprecated and ignored. Opening a workspace does not create context files.")
          },

inputSchema: {
        workspace_id: z.string().describe("Stable workspace_id returned by create_workspace.")
      },

inputSchema: {
        workspace_id: z.string().describe("Stable workspace_id returned by create_workspace.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        path: z.string().describe("Image path relative to workspace root."),
        max_bytes: z.number().int().min(4096).max(2000000).optional().describe("Maximum image bytes. Default: at least 1 MB, capped at 2 MB.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        path: z.string().describe("File path relative to workspace root."),
        edit_tag: z.string().regex(/^[0-9A-F]{4}$/i).describe(
          "Four-character edit tag returned by read. The connector resolves it to retained full content and rejects stale or colliding snapshots."
        ),
        edits: z.array(z.discriminatedUnion("op", [
          z.object({
            op: z.literal("replace"),
            start_line: z.number().int().min(1),
            end_line: z.number().int().min(1).optional(),
            content: z.string()
          }),
          z.object({
            op: z.literal("delete"),
            start_line: z.number().int().min(1),
            end_line: z.number().int().min(1).optional()
          }),
          z.object({
            op: z.literal("insert_before"),
            line: z.number().int().min(1),
            content: z.string()
          }),
          z.object({
            op: z.literal("insert_after"),
            line: z.number().int().min(1),
            content: z.string()
          })
        ])).min(1).max(100).describe(
          "Line operations against the original tagged snapshot. Targets must have been displayed by read."
        )
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        patch: z.string().describe("Git unified diff or native *** Begin Patch text. Paths must stay inside the workspace and avoid blocked paths.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        commands: z.array(z.object({
          command: z.string().min(1).describe("Command to run."),
          label: z.string().max(80).optional().describe("Short label echoed back with the job id."),
          cwd: z.string().optional().describe("Working directory relative to workspace root. Default: ."),
          input_job_ids: z.array(z.string()).max(16).optional().describe("Pin retained output of these workspace jobs while this command runs.")
        }).strict()).min(1).max(OPERATIONAL_LIMITS.CODEXPRO_MAX_JOBS_PER_WORKSPACE.max).describe("Commands started in order, bounded by the current maxCommandsPerCall in server_config."),
        session_id: z.string().optional().describe("Optional bash session id, as for bash.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        job_ids: z.array(z.string().min(1)).min(1).max(JOB_IDS_MAX).describe("Jobs to stop, from bash, start_jobs or jobs.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        message: z.string().min(1).max(8_000).describe("Commit message. First line is the subject."),
        paths: z.array(z.string().min(1)).min(1).max(200).optional().describe("Files to stage and commit, relative to the workspace root. Default: every changed and untracked file.")
      },
      // Git commit hooks can run arbitrary commands, including network access.

inputSchema: {
        workspace_id: workspaceIdSchema(config)
      },

inputSchema: {
        max_sessions: z.number().int().min(1).max(200).optional().describe("Maximum sessions to return. Default: 30."),
        query: z.string().optional().describe("Optional case-insensitive search over session id, title, cwd, and source path.")
      },

inputSchema: {
        workspace_id: workspaceIdSchema(config),
        operations: BATCH_OPERATIONS_SCHEMA.optional().describe("One to twelve inline operations. Cannot be combined with path. Use direct tools for 1-2 simple read-only calls. Serial write/edit children must target distinct files; combine same-file changes into one edit."),
        path: z.string().optional().describe("Workspace-relative JSON batch file to execute. Cannot be combined with operations; mode and continue_on_error come from the file."),
        from: z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/).optional().describe("Stored batches only: start at this operation id, inclusive."),
        from_index: z.number().int().min(0).max(11).optional().describe("Stored batches only: start at this zero-based operation index, inclusive. Cannot be combined with from."),
        mode: z.enum(["serial", "parallel"]).optional().describe("serial by default. parallel is for 3+ independent read-only operations and is limited to parallel-safe tools."),
        continue_on_error: z.boolean().optional().describe("Continue after child failures. Read-only batches only; default false."),
        persist: z.boolean().optional().describe("Inline batches only. Defaults true when the batch contains Bash verification and false for 1-2 read-only operations or other non-verification workflows."),
        session_id: z.string().optional().describe("Bash session authorization, when required by server_config. Inherited by Bash children and never saved in batch definitions."),
        ...(ctx.work && config.writeMode === "workspace" ? { checkpoint: batchCheckpointSchema.optional().describe("Managed serial batch only: atomically save todos, documents and handoff after EVERY selected child succeeds and Bash verification is finished. Uses the outer operation key. Not saved in the batch file; supply again when resuming. Finish/recovery remain explicit work calls.") } : {})
      },
      // Even safe Bash can run project test/build scripts with network effects.
      // With Bash off, workspace mode can still overwrite files or prune batches.
